const int mod = 998244353;
const int maxn = 200005;

int a[maxn];
map<int, int> dp[maxn];

struct BIT {
    int n;
    vector<int> bit;
    BIT() {}
    BIT(int _n) {
        n = _n;
        bit.assign(n + 1, 0);
    }
    void add(int x, int v) {
        while (x <= n) {
            bit[x] += v;
            if (bit[x] >= mod) bit[x] -= mod;
            x += x & -x;
        }
    }
    int sum(int x) {
        int r = 0;
        while (x) {
            r += bit[x];
            if (r >= mod) r -= mod;
            x -= x & -x;
        }
        return r;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    for (int i = 1; i <= n; i++)
        cin >> a[i];

    vector<int> vals = {0};
    vector<int> last, curv;
    for (int i = 1; i <= n; i++) {
        curv.clear();
        curv.push_back(a[i]);
        for (int x : last) {
            int y = x | a[i];
            if (curv.back() != y)
                curv.push_back(y);
        }
        for (int x : curv)
            vals.push_back(x);
        last = curv;
    }

    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    auto id = [&](int x) {
        return lower_bound(vals.begin(), vals.end(), x) - vals.begin() + 1;
    };

    vector<BIT> bit(n + 1);
    for (int i = 0; i <= n; i++)
        bit[i] = BIT(vals.size());

    dp[0][0] = 1;
    bit[0].add(id(0), 1);

    for (int i = 1; i <= n; i++) {
        long long cur = 0;
        for (int j = i - 1; j >= 0; j--) {
            cur |= a[j + 1];
            int ways = bit[j].sum(id((int)cur));
            if (!ways) continue;
            dp[i][(int)cur] += ways;
            if (dp[i][(int)cur] >= mod)
                dp[i][(int)cur] -= mod;
        }

        for (auto [v, w] : dp[i])
            bit[i].add(id(v), w);
    }

    int ans = 0;
    for (auto [_, w] : dp[n]) {
        ans += w;
        if (ans >= mod) ans -= mod;
    }

    cout << ans << '\n';
}